 "content": "def transform(grid):
    # Markers 2 and 8 on the horizontal baseline grow upward as vertical rays.
    # In the demonstrated pattern, 2 has total height 5 and 8 total height 4.
    out = [row[:] for row in grid]
    base = next((r for r, row in enumerate(grid) if any(v in (2, 8) for v in row)), None)
    if base is None:
        return out
    for c, v in enumerate(grid[base]):
        height = {2: 5, 8: 4}.get(v, 0)
        for k in range(1, min(height, base + 1)):
            out[base-k][c] = 1
        if height and base-height+1 >= 0:
            out[base-height+1][c] = v
    return out
